            if (modelsExecutedOrderModel.SizeOption.IsSet)
                writer.WriteNumber("size", modelsExecutedOrderModel.SizeOption.Value!.Value);

            if (modelsExecutedOrderModel.PriceOption.IsSet)
                writer.WriteNumber("price", modelsExecutedOrderModel.PriceOption.Value!.Value);

            if (modelsExecutedOrderModel.TradeIdOption.IsSet)
                writer.WriteNumber("trade_id", modelsExecutedOrderModel.TradeIdOption.Value!.Value);
        }
    }
}
